<?php
namespace App\Core;
final class Router{public static function dispatch():void{$page=$_GET['page']??'dashboard';$action=$_GET['action']??'index';if($page==='login'){require BASE_PATH.'/app/Views/auth/login.php';return;}if($page==='logout'){Auth::logout();}Auth::requireLogin();$map=['dashboard'=>'DashboardController','books'=>'BookController','transactions'=>'TransactionController','users'=>'UserController','reports'=>'ReportController','acquisitions'=>'AcquisitionController','reservations'=>'ReservationController','stock'=>'StockController','barcodes'=>'BarcodeController'];$class=$map[$page]??'DashboardController';$file=BASE_PATH.'/app/Controllers/'.$class.'.php';if(is_file($file))require_once $file;$fq='App\\Controllers\\'.$class;$obj=new $fq();if(!method_exists($obj,$action))$action='index';$obj->$action();}}
